SELECT ph.id::text,ph.ordinal,ph.title,ph.status,count(t.id) FILTER (WHERE t.status<>'cancelled')::bigint task_count,count(t.id) FILTER (WHERE t.status='done')::bigint completed_count,count(t.id) FILTER (WHERE t.checkbox_checked)::bigint checked_count FROM phases ph LEFT JOIN tasks t ON t.phase_id=ph.id WHERE ph.plan_id=$1 AND ph.status<>'removed' GROUP BY ph.id ORDER BY ph.ordinal
